#[allow(non_camel_case_types)]
#[repr(i8)]
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Usage {
  INFERENCE = 0,
  TRAIN = 1,
  INFERENCE_STATIC = 2,

}

const ENUM_MIN_USAGE: i8 = 0;
const ENUM_MAX_USAGE: i8 = 2;

impl<'a> flatbuffers::Follow<'a> for Usage {
  type Inner = Self;
  #[inline]
  fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
    flatbuffers::read_scalar_at::<Self>(buf, loc)
  }
}

impl flatbuffers::EndianScalar for Usage {
  #[inline]
  fn to_little_endian(self) -> Self {
    let n = i8::to_le(self as i8);
    let p = &n as *const i8 as *const Usage;
    unsafe { *p }
  }
  #[inline]
  fn from_little_endian(self) -> Self {
    let n = i8::from_le(self as i8);
    let p = &n as *const i8 as *const Usage;
    unsafe { *p }
  }
}

impl flatbuffers::Push for Usage {
    type Output = Usage;
    #[inline]
    fn push(&self, dst: &mut [u8], _rest: &[u8]) {
        flatbuffers::emplace_scalar::<Usage>(dst, *self);
    }
}

#[allow(non_camel_case_types)]
const ENUM_VALUES_USAGE:[Usage; 3] = [
  Usage::INFERENCE,
  Usage::TRAIN,
  Usage::INFERENCE_STATIC
];

#[allow(non_camel_case_types)]
const ENUM_NAMES_USAGE:[&'static str; 3] = [
    "INFERENCE",
    "TRAIN",
    "INFERENCE_STATIC"
];

pub fn enum_name_usage(e: Usage) -> &'static str {
  let index: usize = e as usize;
  ENUM_NAMES_USAGE[index]
}

