pub struct OpBuilder<'a: 'b, 'b> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b> OpBuilder<'a, 'b> {
  #[inline]
  pub fn add_inputIndexes(&mut self, inputIndexes: flatbuffers::WIPOffset<flatbuffers::Vector<'b , i32>>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Op::VT_INPUTINDEXES, inputIndexes);
  }
  #[inline]
  pub fn add_main_type(&mut self, main_type: OpParameter) {
    self.fbb_.push_slot::<OpParameter>(Op::VT_MAIN_TYPE, main_type, OpParameter::NONE);
  }
  #[inline]
  pub fn add_main(&mut self, main: flatbuffers::WIPOffset<flatbuffers::UnionWIPOffset>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Op::VT_MAIN, main);
  }
  #[inline]
  pub fn add_name(&mut self, name: flatbuffers::WIPOffset<&'b  str>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Op::VT_NAME, name);
  }
  #[inline]
  pub fn add_outputIndexes(&mut self, outputIndexes: flatbuffers::WIPOffset<flatbuffers::Vector<'b , i32>>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Op::VT_OUTPUTINDEXES, outputIndexes);
  }
  #[inline]
  pub fn add_type_(&mut self, type_: OpType) {
    self.fbb_.push_slot::<OpType>(Op::VT_TYPE_, type_, OpType::AbsVal);
  }
  #[inline]
  pub fn add_defaultDimentionFormat(&mut self, defaultDimentionFormat: MNN_DATA_FORMAT) {
    self.fbb_.push_slot::<MNN_DATA_FORMAT>(Op::VT_DEFAULTDIMENTIONFORMAT, defaultDimentionFormat, MNN_DATA_FORMAT::NHWC);
  }
  #[inline]
  pub fn add_externalPath(&mut self, externalPath: flatbuffers::WIPOffset<&'b  str>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Op::VT_EXTERNALPATH, externalPath);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a>) -> OpBuilder<'a, 'b> {
    let start = _fbb.start_table();
    OpBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<Op<'a>> {
    let o = self.fbb_.end_table(self.start_);
    flatbuffers::WIPOffset::new(o.value())
  }
}

pub enum ViewOffset {}
#[derive(Copy, Clone, Debug, PartialEq)]

pub struct View<'a> {
  pub _tab: flatbuffers::Table<'a>,
}

impl<'a> flatbuffers::Follow<'a> for View<'a> {
    type Inner = View<'a>;
    #[inline]
    fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self {
            _tab: flatbuffers::Table { buf: buf, loc: loc },
        }
    }
}

impl<'a> View<'a> {
    #[inline]
    pub fn init_from_table(table: flatbuffers::Table<'a>) -> Self {
        View {
            _tab: table,
        }
    }
    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr>(
        _fbb: &'mut_bldr mut flatbuffers::FlatBufferBuilder<'bldr>,
        args: &'args ViewArgs<'args>) -> flatbuffers::WIPOffset<View<'bldr>> {
      let mut builder = ViewBuilder::new(_fbb);
      if let Some(x) = args.stride { builder.add_stride(x); }
      builder.add_offset(args.offset);
      builder.finish()
    }

    pub const VT_OFFSET: flatbuffers::VOffsetT = 4;
    pub const VT_STRIDE: flatbuffers::VOffsetT = 6;

  #[inline]
  pub fn offset(&self) -> i32 {
    self._tab.get::<i32>(View::VT_OFFSET, Some(0)).unwrap()
  }
  #[inline]
  pub fn stride(&self) -> Option<flatbuffers::Vector<'a, i32>> {
    self._tab.get::<flatbuffers::ForwardsUOffset<flatbuffers::Vector<'a, i32>>>(View::VT_STRIDE, None)
  }
}

