pub struct Region<'a> {
  pub _tab: flatbuffers::Table<'a>,
}

impl<'a> flatbuffers::Follow<'a> for Region<'a> {
    type Inner = Region<'a>;
    #[inline]
    fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self {
            _tab: flatbuffers::Table { buf: buf, loc: loc },
        }
    }
}

impl<'a> Region<'a> {
    #[inline]
    pub fn init_from_table(table: flatbuffers::Table<'a>) -> Self {
        Region {
            _tab: table,
        }
    }
    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr>(
        _fbb: &'mut_bldr mut flatbuffers::FlatBufferBuilder<'bldr>,
        args: &'args RegionArgs<'args>) -> flatbuffers::WIPOffset<Region<'bldr>> {
      let mut builder = RegionBuilder::new(_fbb);
      builder.add_origin(args.origin);
      if let Some(x) = args.size_ { builder.add_size_(x); }
      if let Some(x) = args.dst { builder.add_dst(x); }
      if let Some(x) = args.src { builder.add_src(x); }
      builder.finish()
    }

    pub const VT_SRC: flatbuffers::VOffsetT = 4;
    pub const VT_DST: flatbuffers::VOffsetT = 6;
    pub const VT_SIZE_: flatbuffers::VOffsetT = 8;
    pub const VT_ORIGIN: flatbuffers::VOffsetT = 10;

  #[inline]
  pub fn src(&self) -> Option<View<'a>> {
    self._tab.get::<flatbuffers::ForwardsUOffset<View<'a>>>(Region::VT_SRC, None)
  }
  #[inline]
  pub fn dst(&self) -> Option<View<'a>> {
    self._tab.get::<flatbuffers::ForwardsUOffset<View<'a>>>(Region::VT_DST, None)
  }
  #[inline]
  pub fn size_(&self) -> Option<flatbuffers::Vector<'a, i32>> {
    self._tab.get::<flatbuffers::ForwardsUOffset<flatbuffers::Vector<'a, i32>>>(Region::VT_SIZE_, None)
  }
  #[inline]
  pub fn origin(&self) -> i32 {
    self._tab.get::<i32>(Region::VT_ORIGIN, Some(0)).unwrap()
  }
}

